  const a=v.arte;const temRot=!!String(v.roteiro||'').trim();
  if(!S.sample||!S.assets)return `<div class="field arte"><label>Arte</label><p class="hint">A criação de arte funciona com a página aberta no Claude, com acesso de edição.</p></div>`;
  if(S.arteBusy)return `<div class="field arte"><label>Arte</label><div class="thinking"><span class="dots"><i></i><i></i><i></i></span>${esc(S.arteBusy)}</div></div>`;
